"""
Test to verify that different Annotated types get different serialization strategies.
"""

from dataclasses import dataclass
from typing import Annotated
from typing_extensions import TypeAlias
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]


# Global counters to track which strategy was called
strategy_calls = {
    'positive': 0,
    'negative': 0,
    'fallback': 0
}

def deserialize_positive_int(value):
    strategy_calls['positive'] += 1
    print(f"[POSITIVE STRATEGY] Called {strategy_calls['positive']} times")
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    strategy_calls['negative'] += 1
    print(f"[NEGATIVE STRATEGY] Called {strategy_calls['negative']} times")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


def deserialize_fallback(value):
    strategy_calls['fallback'] += 1
    print(f"[FALLBACK STRATEGY] Called {strategy_calls['fallback']} times")
    return value


@dataclass
class DistinctStrategies(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
            },
            int: {
                "deserialize": deserialize_fallback,  # This should NOT be called for annotated fields
            }
        }


@dataclass  
class SameOriginType(DataClassDictMixin):
    regular_int: int

    class Config:
        serialization_strategy = {
            int: {
                "deserialize": deserialize_fallback,  # This SHOULD be called
            }
        }


def test_distinction():
    """Test that annotated types get distinct strategies."""
    print("=== TESTING ANNOTATED TYPE DISTINCTION ===")

    # Reset counters
    global strategy_calls
    strategy_calls = {'positive': 0, 'negative': 0, 'fallback': 0}

    print("\n1. Creating object with annotated types:")
    obj1 = DistinctStrategies.from_dict({"positive_int": 5, "negative_int": -3})
    print(f"Result: {obj1}")
    print(f"Strategy calls: {strategy_calls}")

    # Check that fallback strategy wasn't called for annotated fields
    if strategy_calls['fallback'] > 0:
        print("✗ FAIL: Fallback strategy was called for annotated fields!")
        return False
    elif strategy_calls['positive'] == 1 and strategy_calls['negative'] == 1:
        print("✓ PASS: Correct strategies were called for annotated fields")
    else:
        print("✗ FAIL: Unexpected strategy call pattern")
        return False

    print("\n2. Creating object with regular int:")
    # Reset counters
    strategy_calls = {'positive': 0, 'negative': 0, 'fallback': 0}

    obj2 = SameOriginType.from_dict({"regular_int": 42})
    print(f"Result: {obj2}")
    print(f"Strategy calls: {strategy_calls}")

    if strategy_calls['fallback'] == 1:
        print("✓ PASS: Fallback strategy was called for regular int")
    else:
        print("✗ FAIL: Fallback strategy was not called for regular int")
        return False

    return True


if __name__ == "__main__":
    success = test_distinction()
    if success:
        print("\n🎉 Distinction test passed!")
    else:
        print("\n❌ Distinction test failed!")
        exit(1)

