"""
Comprehensive test for annotated type serialization strategies.
"""

from dataclasses import dataclass
from typing import Annotated, List
from typing_extensions import TypeAlias
from mashumaro import DataClassDictMixin

# Test various annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"] 
LargeInt: TypeAlias = Annotated[int, "LargeInt", "validation"]
StringWithFormat: TypeAlias = Annotated[str, "email_format"]

def deserialize_positive_int(value):
    if value <= 0:
        raise ValueError("PositiveInt must be > 0")
    return value

def deserialize_negative_int(value):
    if value >= 0:
        raise ValueError("NegativeInt must be < 0")
    return value

def deserialize_large_int(value):
    if value < 1000:
        raise ValueError("LargeInt must be >= 1000")
    return value

def deserialize_email(value):
    if "@" not in value:
        raise ValueError("Email must contain @")
    return value

@dataclass
class ComplexAnnotatedTypes(DataClassDictMixin):
    pos_int: PositiveInt
    neg_int: NegativeInt
    large_int: LargeInt
    email: StringWithFormat

    class Config:
        serialization_strategy = {
            PositiveInt: {"deserialize": deserialize_positive_int},
            NegativeInt: {"deserialize": deserialize_negative_int},
            LargeInt: {"deserialize": deserialize_large_int},
            StringWithFormat: {"deserialize": deserialize_email},
        }

@dataclass
class MixedTypes(DataClassDictMixin):
    annotated_int: PositiveInt
    regular_int: int
    annotated_str: StringWithFormat
    regular_str: str

    class Config:
        serialization_strategy = {
            PositiveInt: {"deserialize": deserialize_positive_int},
            StringWithFormat: {"deserialize": deserialize_email},
            int: {"deserialize": lambda x: x * 2},  # Double regular ints
            str: {"deserialize": lambda x: x.upper()},  # Uppercase regular strings
        }

@dataclass
class NestedAnnotated(DataClassDictMixin):
    annotated_list: List[PositiveInt]

    class Config:
        serialization_strategy = {
            PositiveInt: {"deserialize": deserialize_positive_int},
        }

def test_complex_annotated():
    """Test complex annotated type scenarios."""
    print("=== COMPLEX ANNOTATED TYPES TEST ===")

    try:
        obj = ComplexAnnotatedTypes.from_dict({
            "pos_int": 5,
            "neg_int": -3, 
            "large_int": 2000,
            "email": "test@example.com"
        })
        print(f"✓ Complex annotated types work: {obj}")
        return True
    except Exception as e:
        print(f"✗ Complex annotated types failed: {e}")
        return False

def test_mixed_types():
    """Test mixing annotated and regular types."""
    print("\n=== MIXED TYPES TEST ===")

    try:
        obj = MixedTypes.from_dict({
            "annotated_int": 5,
            "regular_int": 21,
            "annotated_str": "test@example.com",
            "regular_str": "hello"
        })
        print(f"✓ Mixed types work: {obj}")

        # Check that strategies were applied correctly
        if obj.annotated_int == 5 and obj.regular_int == 42 and obj.annotated_str == "test@example.com" and obj.regular_str == "HELLO":
            print("✓ Strategies applied correctly")
            return True
        else:
            print(f"✗ Strategy application incorrect: {obj}")
            return False

    except Exception as e:
        print(f"✗ Mixed types failed: {e}")
        return False

def test_nested_annotated():
    """Test nested annotated types."""
    print("\n=== NESTED ANNOTATED TYPES TEST ===")

    try:
        obj = NestedAnnotated.from_dict({
            "annotated_list": [1, 2, 3]
        })
        print(f"✓ Nested annotated works: {obj}")
        return True
    except Exception as e:
        print(f"✗ Nested annotated failed: {e}")
        return False

def test_validation_errors():
    """Test that validation errors are properly handled."""
    print("\n=== VALIDATION ERRORS TEST ===")

    # Test PositiveInt validation
    try:
        obj = ComplexAnnotatedTypes.from_dict({
            "pos_int": -1,  # Should fail
            "neg_int": -3,
            "large_int": 2000,
            "email": "test@example.com"
        })
        print(f"✗ Should have failed validation: {obj}")
        return False
    except Exception as e:
        print(f"✓ Correctly caught validation error: {type(e).__name__}")

    return True

if __name__ == "__main__":
    tests = [
        test_complex_annotated,
        test_mixed_types, 
        test_nested_annotated,
        test_validation_errors
    ]

    results = []
    for test in tests:
        results.append(test())

    if all(results):
        print("\n🎉 All comprehensive tests passed!")
    else:
        print(f"\n❌ {sum(results)}/{len(results)} tests passed!")
        exit(1)

