"""
Reproduce the exact test case from commit 058f222
"""

from dataclasses import dataclass
from datetime import date, datetime
from typing_extensions import Annotated
from mashumaro import DataClassDictMixin
from mashumaro.config import BaseConfig


def test_annotated_with_overriden_methods():
    @dataclass
    class DataClass(DataClassDictMixin):
        foo: Annotated[date, "foo"]
        bar: Annotated[date, "bar"]
        baz: Annotated[date, "baz"]

        class Config(BaseConfig):
            serialization_strategy = {
                Annotated[date, "foo"]: {
                    "serialize": date.toordinal,
                    "deserialize": date.fromordinal,
                },
                Annotated[date, "bar"]: {
                    "serialize": date.isoformat,
                    "deserialize": date.fromisoformat,
                },
                date: {
                    "serialize": lambda x: datetime(
                        x.year, x.month, x.day
                    ).timestamp(),
                    "deserialize": (
                        lambda x: datetime.fromtimestamp(x).date()
                    ),
                },
            }

    obj = DataClass(
        foo=date(2023, 6, 12),
        bar=date(2023, 6, 12),
        baz=date(2023, 6, 12),
    )

    print("Original object:", obj)

    # Test serialization
    serialized = obj.to_dict()
    print("Serialized:", serialized)

    expected = {
        "bar": "2023-06-12",
        "baz": 1686517200.0,
        "foo": 738683,
    }

    print("Expected:", expected)

    # Test deserialization
    deserialized = DataClass.from_dict(
        {"bar": "2023-06-12", "baz": 1686517200.0, "foo": 738683}
    )
    print("Deserialized:", deserialized)

    print("Objects equal:", deserialized == obj)

    return serialized == expected and deserialized == obj


if __name__ == "__main__":
    success = test_annotated_with_overriden_methods()
    if success:
        print("\n✅ Test passed!")
    else:
        print("\n❌ Test failed!")
        exit(1)

